public static void glfwDestroyWindow(long window) {
  try {
    internalGetWindow(window);
  } catch (IllegalArgumentException e) {
    // Handle the case where the window does not exist in the map, e.g., log the error or notify the user
    System.err.println("Error: Window does not exist. " + e.getMessage());
    return;
  }
  mGLFWWindowMap.remove(window);
  nglfwSetShowingWindow(mGLFWWindowMap.size() == 0 ? 0 : mGLFWWindowMap.keyAt(mGLFWWindowMap.size() - 1));
}
